class Solution {
public:
    vector<int> countSubgraphsForEachDiameter(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]-1].push_back(e[1]-1);
            adj[e[1]-1].push_back(e[0]-1);
        }
        vector<int> ans(n-1, 0);
        for (int mask = 1; mask < (1 << n); mask++) {
            if ((mask & (mask - 1)) == 0) continue;
            int start = -1;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) { start = i; break; }
            }
            int popcount = __builtin_popcount(mask);
            vector<int> dist(n, -1);
            queue<int> q;
            q.push(start);
            dist[start] = 0;
            int cnt = 1;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) {
                    if ((mask & (1 << v)) && dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        cnt++;
                        q.push(v);
                    }
                }
            }
            if (cnt != popcount) continue;
            int u = start, maxd = 0;
            for (int i = 0; i < n; i++) {
                if (dist[i] > maxd) { maxd = dist[i]; u = i; }
            }
            fill(dist.begin(), dist.end(), -1);
            q.push(u);
            dist[u] = 0;
            int diam = 0;
            while (!q.empty()) {
                int x = q.front(); q.pop();
                for (int v : adj[x]) {
                    if ((mask & (1 << v)) && dist[v] == -1) {
                        dist[v] = dist[x] + 1;
                        if (dist[v] > diam) diam = dist[v];
                        q.push(v);
                    }
                }
            }
            ans[diam - 1]++;
        }
        return ans;
    }
};
